insert into question_pyq_meta (question_id, appear_count, years, exams, verified)
select id, appear_count, coalesce((select array_agg(v::int) from jsonb_array_elements_text(years) as v), '{}')::int[], coalesce((select array_agg(v) from jsonb_array_elements_text(exams) as v), '{}')::text[], verified
from jsonb_to_recordset($json$[{"id":"che-st-236","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Complete neutralisation of sulphuric acid uses $n = 2$. The equivalent mass of $\\mathrm{H_2SO_4}$ (M = 98) is therefore","options":["24.5 g eq$^{-1}$","49 g eq$^{-1}$","98 g eq$^{-1}$","196 g eq$^{-1}$"],"answer_index":1,"explanation":"$E = 98/2 = 49$ g eq$^{-1}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"equivalents-normality","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-237","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A bottle labelled 0.50 M $\\mathrm{H_2SO_4}$ is used as a dibasic acid. The normality of that solution is","options":["0.25 N","0.50 N","1.0 N","2.0 N"],"answer_index":2,"explanation":"$N = M \\times n = 0.50 \\times 2 = 1.0$ N.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"equivalents-normality","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-238","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"In acidic medium $\\mathrm{KMnO_4}$ is reduced to $\\mathrm{Mn^{2+}}$. The $n$-factor of permanganate in that change is","options":["1","3","5","7"],"answer_index":2,"explanation":"Mn falls from $+7$ to $+2$, a five-electron change, so $n = 5$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"equivalents-normality","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-239","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Potassium permanganate (M = 158 g mol$^{-1}$) used in acidic titration has equivalent mass","options":["31.6 g eq$^{-1}$","52.7 g eq$^{-1}$","79.0 g eq$^{-1}$","158 g eq$^{-1}$"],"answer_index":0,"explanation":"$E = 158/5 = 31.6$ g eq$^{-1}$ for the five-electron acidic reduction.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"equivalents-normality","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-240","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Twenty-five millilitres of 0.20 N $\\mathrm{H_2SO_4}$ are titrated with 0.10 N NaOH. The volume of alkali required for complete neutralisation is","options":["12.5 mL","25 mL","50 mL","100 mL"],"answer_index":2,"explanation":"$N_1V_1 = N_2V_2$ gives $V(\\mathrm{NaOH}) = (0.20 \\times 25)/0.10 = 50$ mL.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"equivalents-normality","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-241","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A one-molar aqueous solution is prepared so that one litre of the finished solution contains","options":["1 mol of solute","1 mol of solvent only","1 g of solute","1 kg of solute"],"answer_index":0,"explanation":"Molarity is moles of solute per litre of solution; 1 M means 1 mol in 1 L of solution.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"molarity-dilution","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-242","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Half a mole of glucose is dissolved and the solution is made up to 250 mL. The molarity of that solution is","options":["0.50 M","1.0 M","2.0 M","4.0 M"],"answer_index":2,"explanation":"$M = 0.50 / 0.250 = 2.0$ mol L$^{-1}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"molarity-dilution","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-243","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"When a solution is diluted with solvent, the product $M_1V_1$ compared with $M_2V_2$ is","options":["larger after dilution","smaller after dilution","unchanged, because solute moles stay the same","equal to the density"],"answer_index":2,"explanation":"Dilution conserves the amount of solute, so $M_1V_1 = M_2V_2$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"molarity-dilution","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-244","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Two moles of NaOH pellets are dissolved and the solution is made up to 1.00 L. The molarity of the alkali is","options":["0.50 M","1.0 M","2.0 M","4.0 M"],"answer_index":2,"explanation":"$M = 2.0\\ \\mathrm{mol} / 1.00\\ \\mathrm{L} = 2.0$ M.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"molarity-dilution","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-245","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Four grams of NaOH (M = 40 g mol$^{-1}$) are dissolved and made up to 500 mL. The molarity of the solution is","options":["0.10 M","0.20 M","0.40 M","2.0 M"],"answer_index":1,"explanation":"Moles of NaOH $= 4/40 = 0.10$; $M = 0.10 / 0.50 = 0.20$ M.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"molarity-dilution","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
    id text,
    chapter_id text,
    subject_id text,
    stem text,
    options jsonb,
    answer_index int,
    explanation text,
    images jsonb,
    source jsonb,
    difficulty text,
    concept_id text,
    appear_count int,
    years jsonb,
    exams jsonb,
    verified boolean
  )
on conflict (question_id) do update set
  appear_count = excluded.appear_count,
  years = excluded.years,
  exams = excluded.exams,
  verified = excluded.verified;